def create_output_excerpts(self, test_info):
  """Convenient method for creating excerpts of adb logcat.

  This copies logcat lines from self.adb_logcat_file_path to an excerpt
  file, starting from the location where the previous excerpt ended.

  Call this method at the end of: `setup_class`, `teardown_test`, and
  `teardown_class`.

  Args:
    test_info: `self.current_test_info` in a Mobly test.

  Returns:
    List of strings, the absolute paths to excerpt files.
  """
  @icontract.ensure(isinstance(test_info, dict))
  @icontract.snapshot(self.adb_logcat_file_path)
  @icontract.snapshot(test_info)
  # The return value should be a list of strings
  @icontract.ensure(isinstance(return_value, list))
  # Each element in the list should be a string
  @icontract.ensure(all(isinstance(x, str) for x in return_value))
  # The paths should be absolute
  @icontract.ensure(all(os.path.isabs(x) for x in return_value))
  # The paths should exist
  @icontract.ensure(all(os.path.exists(x) for x in return_value))

